const days=[{day:'Lunes',short:'MON',file:'monday',names:['Gel Bergonio'],roles:['SK Kagawad']},{day:'Martes',short:'TUE',file:'tuesday',names:['Ernest Bragais','Kristine De Ocampo'],roles:['SK Treasurer','SK Secretary']},{day:'Miyerkules',short:'WED',file:'wednesday',names:['Sherwin Estanislao'],roles:['SK Kagawad']},{day:'Huwebes',short:'THU',file:'thursday',names:['Rembert Natividad'],roles:['SK Kagawad']},{day:'Biyernes',short:'FRI',file:'friday',names:['Arvin Capiral'],roles:['SK Chairman']},{day:'Sabado',short:'SAT',file:'saturday',names:['Kath Irag'],roles:['SK Kagawad']},{day:'Linggo',short:'SUN',file:'sunday',names:['Roland Reyes'],roles:['SK Kagawad']}];
const currentDay=new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'Asia/Manila'}).format(new Date()).toUpperCase();let selected=days.findIndex(d=>d.short===currentDay);if(selected<0)selected=0;
function selectDay(index){selected=index;const d=days[index];document.querySelectorAll('[data-day]').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index))});$('#day-kicker').textContent=d.day.toUpperCase()+' / OFFICER'+(d.names.length>1?'S':'')+' OF THE DAY';$('#officer-name').innerHTML=d.names.map((name,i)=>`<span>${esc(name)}<small>${esc(d.roles[i])}</small></span>`).join('');$('#poster-link').href='./duty/'+d.file+'.jpg';$('#day-poster').src='./duty/'+d.file+'.jpg';$('#day-poster').alt=d.day+': '+d.names.join(' at ');}
$('.day-switch').innerHTML=days.map((d,i)=>`<button data-day="${i}" aria-pressed="false"><small>${d.short}</small><span>${d.day}</span>${d.short===currentDay?'<i aria-label="Ngayong araw"></i>':''}</button>`).join('');$('.day-switch').onclick=e=>{const b=e.target.closest('[data-day]');if(b)selectDay(Number(b.dataset.day))};selectDay(selected);
